```ts
// Public corpus runner (DESIGN.md §"Candidate generation", task F19).
// ...

export interface CorpusCandidate { repo: string; score: number }
export interface CorpusOptions {
  candidates: CorpusCandidate[];
  top: number;
  review: (repo: string) => Promise<unknown>;
  write: (path: string, data: unknown) => Promise<void>;
}
export interface CorpusResult {
  done: string[];
  failed: { repo: string; reason: string }[];
}

export const CORPUS_DIR = "reports/corpus";
export const corpusDir = (repo: string): string => `${CORPUS_DIR}/${repo.replace("/", "__")}`;
export const reviewPath = (repo: string): string => `${corpusDir(repo)}/review.json`;
export const INDEX_PATH = `${CORPUS_DIR}/index.json`;

export function rankTop(candidates, top): CorpusCandidate[] {
  return [...candidates].sort((a,b) => b.score - a.score || a.repo.localeCompare(b.repo)).slice(0, clampTop(top));
}

export async function runCorpus(opts): Promise<CorpusResult> {
  const done: string[] = [];
  const failed = [];
  for (const { repo } of rankTop(opts.candidates, opts.top)) {
    try {
      const report = await opts.review(repo);
      await opts.write(reviewPath(repo), report);
      done.push(repo);
    } catch (e) {
      failed.push({ repo, reason: message(e) });
    }
  }
  const result = { done, failed };
  await opts.write(INDEX_PATH, result);
  return result;
}
