import { describe, expect, test } from "bun:test";
import {
  CORPUS_DIR,
  INDEX_PATH,
  rankTop,
  repoSlug,
  reviewPath,
  runCorpus,
  type CorpusCandidate,
} from "../scripts/corpus-run";

/** Records the calls the runner makes, so ordering and concurrency are observable. */
function harness(opts: {
  fail?: Record<string, unknown>;
  failWrite?: string[];
  reports?: Record<string, unknown>;
}) {
  const events: string[] = [];
  const writes: { path: string; data: unknown }[] = [];
  let inFlight = 0;
  let maxInFlight = 0;
  const review = async (repo: string) => {
    inFlight++;
    maxInFlight = Math.max(maxInFlight, inFlight);
    events.push("review:" + repo);
    await Promise.resolve();
    inFlight--;
    if (opts.fail && repo in opts.fail) throw opts.fail[repo];
    return opts.reports?.[repo] ?? { repo, summary: "ok" };
  };
  const write = async (path: string, data: unknown) => {
    if (opts.failWrite?.includes(path)) throw new Error("disk full");
    writes.push({ path, data });
    events.push("write:" + path);
  };
  return { events, writes, review, write, maxInFlight: () => maxInFlight };
}

const candidates: CorpusCandidate[] = [
  { repo: "b/b", score: 5 },
  { repo: "a/a", score: 9 },
  { repo: "c/c", score: 5 },
  { repo: "d/d", score: 1 },
];

describe("rankTop", () => {
  test("takes the highest scores, ties broken by repo name", () => {
    expect(rankTop(candidates, 3).map((c) => c.repo)).toEqual(["a/a", "b/b", "c/c"]);
  });

  test("does not mutate the caller's array", () => {
    const input = [...candidates];
    rankTop(input, 4);
    expect(input).toEqual(candidates);
  });

  test("top larger than the list takes everything; non-positive takes nothing", () => {
    expect(rankTop(candidates, 99).map((c) => c.repo)).toEqual(["a/a", "b/b", "c/c", "d/d"]);
    expect(rankTop(candidates, 0)).toEqual([]);
    expect(rankTop(candidates, -2)).toEqual([]);
  });

  test("ignores candidates beyond the top", () => {
    expect(rankTop(candidates, 1).map((c) => c.repo)).toEqual(["a/a"]);
  });
});

describe("paths", () => {
  test("slugs the repo and nests review.json under reports/corpus", () => {
    expect(repoSlug("teslamint/entirecontext")).toBe("teslamint__entirecontext");
    expect(reviewPath("teslamint/entirecontext")).toBe("reports/corpus/teslamint__entirecontext/review.json");
    expect(CORPUS_DIR).toBe("reports/corpus");
    expect(INDEX_PATH).toBe("reports/corpus/index.json");
  });
});

describe("runCorpus", () => {
  test("reviews the top candidates sequentially and writes each review immediately", async () => {
    const h = harness({});
    const result = await runCorpus({ candidates, top: 2, review: h.review, write: h.write });

    expect(h.maxInFlight()).toBe(1); // sequential, never parallel
    expect(h.events).toEqual([
      "review:a/a",
      "write:reports/corpus/a__a/review.json",
      "review:b/b",
      "write:reports/corpus/b__b/review.json",
      "write:reports/corpus/index.json",
    ]);
    expect(result).toEqual({ done: ["a/a", "b/b"], failed: [] });
  });

  test("writes the review's own data to the repo's review.json", async () => {
    const h = harness({ reports: { "a/a": { repo: "a/a", n: 7 } } });
    await runCorpus({ candidates, top: 1, review: h.review, write: h.write });
    expect(h.writes[0]).toEqual({ path: "reports/corpus/a__a/review.json", data: { repo: "a/a", n: 7 } });
  });

  test("writes index.json last, holding the same done and failed lists it returns", async () => {
    const h = harness({ fail: { "b/b": new Error("clone failed") } });
    const result = await runCorpus({ candidates, top: 3, review: h.review, write: h.write });

    const last = h.writes.at(-1)!;
    expect(last.path).toBe(INDEX_PATH);
    expect(last.data).toEqual(result);
    expect(result).toEqual({ done: ["a/a", "c/c"], failed: [{ repo: "b/b", reason: "clone failed" }] });
    expect(h.events.at(-1)).toBe("write:" + INDEX_PATH);
  });

  test("a throwing review is recorded with its message and does not stop the run", async () => {
    const h = harness({ fail: { "a/a": new Error("no checkpoints") } });
    const result = await runCorpus({ candidates, top: 4, review: h.review, write: h.write });

    expect(result.failed).toEqual([{ repo: "a/a", reason: "no checkpoints" }]);
    expect(result.done).toEqual(["b/b", "c/c", "d/d"]);
    // every later repo was still reviewed despite the first failure
    expect(h.events.filter((e) => e.startsWith("review:"))).toEqual([
      "review:a/a",
      "review:b/b",
      "review:c/c",
      "review:d/d",
    ]);
  });

  test("records a non-Error throw as a string reason", async () => {
    const h = harness({ fail: { "a/a": "boom" } });
    const result = await runCorpus({ candidates, top: 1, review: h.review, write: h.write });
    expect(result.failed).toEqual([{ repo: "a/a", reason: "boom" }]);
    expect(result.done).toEqual([]);
  });

  test("a failed review writes no review.json for that repo", async () => {
    const h = harness({ fail: { "a/a": new Error("nope") } });
    await runCorpus({ candidates, top: 2, review: h.review, write: h.write });
    expect(h.writes.map((w) => w.path)).toEqual(["reports/corpus/b__b/review.json", INDEX_PATH]);
  });

  test("a failing write is recorded and the run continues", async () => {
    const h = harness({ failWrite: ["reports/corpus/a__a/review.json"] });
    const result = await runCorpus({ candidates, top: 2, review: h.review, write: h.write });
    expect(result).toEqual({ done: ["b/b"], failed: [{ repo: "a/a", reason: "disk full" }] });
  });

  test("top 0 reviews nothing but still writes the index", async () => {
    const h = harness({});
    const result = await runCorpus({ candidates, top: 0, review: h.review, write: h.write });
    expect(h.events).toEqual(["write:" + INDEX_PATH]);
    expect(result).toEqual({ done: [], failed: [] });
  });

  test("an empty candidate list writes an empty index", async () => {
    const h = harness({});
    const result = await runCorpus({ candidates: [], top: 5, review: h.review, write: h.write });
    expect(result).toEqual({ done: [], failed: [] });
    expect(h.writes).toEqual([{ path: INDEX_PATH, data: { done: [], failed: [] } }]);
  });

  test("a repo whose review succeeds appears in done exactly once", async () => {
