// Public corpus runner (task F19): review the top public repos from the corpus candidates.
// Takes the `top` highest-score candidates (ties broken by repo name), reviews them sequentially and keeps
// going when one fails. Every success lands in `reports/corpus/<owner>__<repo>/review.json`; the run ends with
// `reports/corpus/index.json` listing what was done and what failed. `review` and `write` are injected so the
// loop is testable without network or disk.
//
//   roster-side wiring: bun scripts/corpus-run.ts [--candidates reports/corpus/candidates.json] [--top 5] [--cache .roster/cache]

import { mkdirSync } from "node:fs";
import { dirname, join } from "node:path";

export interface CorpusCandidate {
  repo: string;
  score: number;
}

export interface CorpusOptions {
  candidates: CorpusCandidate[];
  top: number;
  review: (repo: string) => Promise<unknown>;
  write: (path: string, data: unknown) => Promise<void>;
}

export interface CorpusFailure {
  repo: string;
  reason: string;
}

export interface CorpusResult {
  done: string[];
  failed: CorpusFailure[];
}

export const CORPUS_DIR = "reports/corpus";
export const INDEX_PATH = `${CORPUS_DIR}/index.json`;

/** `<owner>__<repo>`, the same flattening scripts/corpus-find.ts uses for its fetch cache. */
export const repoSlug = (repo: string): string => repo.replace("/", "__");

/** Where one repo's review lands: `reports/corpus/<owner>__<repo>/review.json`. */
export const reviewPath = (repo: string): string => `${CORPUS_DIR}/${repoSlug(repo)}/review.json`;

/** The `top` highest-score candidates; ties broken by repo name. A non-positive `top` selects nothing. */
export function rankTop(candidates: CorpusCandidate[], top: number): CorpusCandidate[] {
  const n = Math.floor(top);
  if (!Number.isFinite(n) || n <= 0) return [];
  return [...candidates].sort((a, b) => b.score - a.score || a.repo.localeCompare(b.repo)).slice(0, n);
}

/** An error's message; a non-Error throw is stringified so the failure list always carries a reason. */
export const failReason = (e: unknown): string =>
  e instanceof Error && e.message ? e.message : String(e);

/**
 * Review the top candidates one at a time. A review (or the write of its result) that throws is recorded in
 * `failed` and does not stop the run; `index.json` is written once, after the last repo.
 */
export async function runCorpus(opts: CorpusOptions): Promise<CorpusResult> {
  const done: string[] = [];
  const failed: CorpusFailure[] = [];
  for (const { repo } of rankTop(opts.candidates, opts.top)) {
    try {
      const report = await opts.review(repo);
      await opts.write(reviewPath(repo), report);
      done.push(repo);
    } catch (e) {
      failed.push({ repo, reason: failReason(e) });
    }
  }
  const result: CorpusResult = { done, failed };
  await opts.write(INDEX_PATH, result);
  return result;
}

// ---- CLI wiring (not unit-tested; exercised by the live run) ----

const jsonWrite = async (path: string, data: unknown): Promise<void> => {
  mkdirSync(dirname(path), { recursive: true });
  await Bun.write(path, JSON.stringify(data, null, 2) + "\n");
};

async function main() {
  const argv = process.argv.slice(2);
  const opt = (k: string, d: string) => (argv.includes(k) ? (argv[argv.indexOf(k) + 1] ?? d) : d);
  const candidatesPath = opt("--candidates", `${CORPUS_DIR}/candidates.json`);
  const cache = opt("--cache", ".roster/cache");
  const { rankCandidates } = await import("./corpus-find");
  const { runReview } = await import("../src/cli/review");
  const found = rankCandidates((await Bun.file(candidatesPath).json()) as any[]);

  const review = async (repo: string) => {
    const out = join(CORPUS_DIR, repoSlug(repo));
    const code = await runReview({ repo, out, cache });
    if (code !== 0) throw new Error(`roster review exited ${code}`);
    return (await Bun.file(reviewPath(repo)).json()) as unknown;
  };

  const { done, failed } = await runCorpus({
    candidates: found.map((c) => ({ repo: c.repo, score: c.score })),
    top: Number(opt("--top", "5")),
    review,
    write: jsonWrite,
  });
  for (const f of failed) console.error(`[failed] ${f.repo}: ${f.reason}`);
  console.log(`corpus run: ${done.length} done, ${failed.length} failed → ${INDEX_PATH}`);
}

if (import.meta.main) await main();

